using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using UnityEngine;

public class Mover : MonoBehaviour
{
    NativeArray<float> positions, velocities;   // Allocator.Persistent, allocated in Awake

    void Update()
    {
        var job = new MoveJob { positions = positions, velocities = velocities, dt = Time.deltaTime };
        JobHandle h = job.Schedule();
        h.Complete();   // for now; lesson 4 moves it later in the frame
    }
}

[BurstCompile]
struct MoveJob : IJob
{
    public NativeArray<float> positions;
    [ReadOnly] public NativeArray<float> velocities;
    public float dt;   // main-thread APIs such as Time are not available in a job

    public void Execute()
    {
        for (int i = 0; i < positions.Length; i++)
            positions[i] += velocities[i] * dt;
    }
}
